    try:
        if layer.GetFeatureCount() == 0:
            msg = f"item {feature_id} is not found"
            LOGGER.error(msg)
            raise ProviderItemNotFoundError(msg)
        # Ignore gdal error
        next_feature = _ignore_gdal_error(layer, "GetNextFeature")
        if next_feature:
            if all(val is None for val in next_feature.items().values()):
                self.gdal.Error(self.gdal.CE_Failure, 1, "Object properties are all null")
        else:
            raise RuntimeError(f"GDAL has returned a null feature for item {feature_id}")
        return next_feature
    except RuntimeError as gdalerr:
        LOGGER.error(self.gdal.GetLastErrorMsg())
        raise gdalerr
