Source code in <code>src/georama/features/pygeoapi_providers/ogr.py</code> <pre><code>def _ogr_feature_to_json(
    self,
    ogr_feature,
    skip_geometry=False,
    crs_transform_out=None,
):
    if self.geom_field is not None:
        geom = ogr_feature.GetGeomFieldRef(self.geom_field)
    else:
        geom = ogr_feature.GetGeometryRef()

    if crs_transform_out is not None:
        # Optionally reproject the geometry
        geom.Transform(crs_transform_out)

    # NB With GDAL &gt;= 3.3 seems that Axis is swapped for e.g.
    # EPSG:4258 in ExportToJson where it shouldn't. See #1174.
    # Suppress swapping by unassigning SpatialReference
    geom.AssignSpatialReference(None)
    json_feature = ogr_feature.ExportToJson(as_object=True)

    if skip_geometry:
        json_feature["geometry"] = None

    # Drop non-defined properties
    if self.properties:
        props = json_feature["properties"]
        dropping_keys = deepcopy(props).keys()
        for item in dropping_keys:
            if item not in self.properties:
                props.pop(item)

    try:
        json_feature["id"] = json_feature["properties"].pop(
            self.id_field, json_feature["id"]
        )
    except KeyError as err:
        LOGGER.error(f"Cannot use configured id_field nor fid as id, err={err}")  # noqa

    return json_feature
</code></pre>

Source code in <code>src/georama/features/views.py</code> <pre><code>def create_resource(
    self, published_as: PublishedAsOgcApiFeatures, request: HttpRequest
) -&gt; dict:
    editable = (
        published_as.has_update_permission(request.user, appname)
        or published_as.has_create_permission(request.user, appname)
        or published_as.has_delete_permission(request.user, appname)
    )

    features_properties = []
    if published_as.column_permission:
        features_properties = [
            c.name
            for c in published_as.columns.all()
            if c.has_general_permission(request.user, appname)
        ]

    if published_as.dataset.driver.upper() == "POSTGRES":
        provider = self.create_postgres_provider(
            published_as, editable, features_properties
        )
    elif published_as.dataset.driver.upper() == "OGR":
        provider = self.create_ogr_provider(published_as, editable, features_properties)
    else:
        raise NotImplementedError

    return {
        "type": "collection",
        "title": published_as.title,
        "description": published_as.description,
        # TODO: add keywords into models
        "keywords": [],
        "linked-data": {
            "context": [
                {"datetime": "https://schema.org/DateTime"},
                {
                    "vocab": "https://example.com/vocab#",
                    "stn_id": "vocab:stn_id",
                    "value": "vocab:value",
                },
            ]
        },
        "links": [],
        "extents": {
            "spatial": {
                "bbox": BBox.from_string(published_as.dataset.bbox).to_list(),
                "crs": "http://www.opengis.net/def/crs/OGC/1.3/CRS84",
            }
        },
        "providers": [provider],
        "limits": {
            "on_exceed": published_as.on_exceed,
            "max_items": published_as.max_items,
            "default_items": published_as.default_items,
        },
    }
